  "cost-7.html": {
    "slug": "cost-agent-history-growth",
    "title": "四格看懂：输入主导：62:1 的 I/O Ratio",
    "takeaway": "多轮任务要看累计输入、输出、工具与重试开销，结合流程分析异常。",
    "panels": [
      {
        "label": "每轮需要当前上下文",
        "text": "如果不断追加完整历史，后续输入会越来越长。",
        "alt": "循环虎在环形轨道上看到任务车每经过一圈就多带一叠资料。"
      },
      {
        "label": "总成本是跨轮累计",
        "text": "不能只拿最后一轮或一次成功调用代表整个任务。",
        "alt": "循环虎把每轮筹码依次倒入累计账盘。"
      },
      {
        "label": "比率只是诊断信号",
        "text": "输入输出比例高可能有多种原因，不能靠单一阈值判定空转。",
        "alt": "循环虎用放大镜比较长文阅读任务与重复工具调用任务的两本记录。"
      },
      {
        "label": "从流程定位浪费",
        "text": "缩小工具返回、合理检索与管理历史，再评估结果。",
        "alt": "循环虎给任务车卸下重复资料，保留目标卡和关键证据后重新试跑。"
      }
    ]
  },
